ription","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_6e4d033d011196fd$::jsonb) union all select 'shared:official:equipment:es:b2a16fd04dd10bb6241cffcb' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b2a16fd04dd10bb6241cffcb' and payload#>'{features}'=$verify_c6a3859e8e841b24$[{"id":"legacy-bonus-0","kind":"passive","name":"All","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga un bono de +1 a todas las tiradas de salvación.","showInActions":false},{"id":"legacy-bonus-1","kind":"passive","name":"AC","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +1 a la CA.","showInActions":false},{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":2,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a la CA y a las tiradas de salvación mientras lleves puesto este anillo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_c6a3859e8e841b24$::jsonb) union all select 'shared:official:equipment:es:b2ccc2c141497ce32fa56712' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:b2ccc2c141497ce32fa56712' and payload#>'{features}'=$verify_b95dbe2142d2cb82$[{"id":"spellcasting-bonus","kind":"passive","name":"Bonificación de conjuros +1","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este amuleto lleva el símbolo de una deidad. Mientras lleves puesto el símbolo sagrado, obtienes un bonificador de +1 a las tiradas de ataque y a las CD de las tiradas de salvación de tus conjuros.\n\nDuración: Mientras se cumplan los requisitos del objeto..","showInActions":false},{"id":"daily-property","kind":"other","name":"Registrar Canalizar divinidad gratuito","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"Mientras lleves puesto el amuleto, puedes usar Canalizar divinidad sin gastar uno de sus usos normales. Una vez usada esta propiedad, no puede volver a usarse hasta el siguiente amanecer. El amuleto no cambia el tiempo de activación del efecto de Canalizar divinidad que elijas.\n\nDuración: Según el rasgo de clase..\n\nCoste: 1 Canalizar divinidad sin gastar un uso.","showInActions":false}]$verify_b95dbe2142d2cb82$::jsonb))t;